// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

// Load technical font for the blueprint look
const { fontFamily: robotoMono } = loadRobotoMono();



export type BlueprintReadProps = Record<string, any>;

const TitleBlockText: React.FC<{ y: number; label: string; value: string; color: string }> = ({ y, label, value, color }) => (
  <div style={{ position: "absolute", left: 3200, top: y, fontSize: 24, color, display: "flex", flexDirection: "column", gap: 6 }}>
    <span style={{ fontSize: 18, opacity: 0.6 }}>{label}</span>
    <span style={{ fontWeight: "bold", fontSize: 26 }}>{value}</span>
  </div>
);

const BlueprintRead: React.FC<BlueprintReadProps> = ({
  backgroundColor = "#f4f6f8",
  textColor = "#1e293b",
  selectionColor = "#ef4444",
  highlightColor = "#eab308",
  stampColor = "#3b82f6",
  noteTitle = "3. CRITICAL INSTRUCTION",
  mainMessage = "ALWAYS READ THE NOTES ON YOUR BLUEPRINTS. THE DETAILS HERE ENSURE STRUCTURAL INTEGRITY AND COMPLIANCE. IGNORING THESE WILL CAUSE DISASTROUS ERRORS IN CONSTRUCTION.",
  brandingText = "MALLOY STUDIO",
  transparentBackground = false,
  durationInSeconds = 10,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Blueprint native resolution optimized for 16:9
  const bpW = 3840;
  const bpH = 2160;

  // Timeline markers relative to fps
  const totalFrames = durationInSeconds * fps;
  const tSetup = 15;
  const tBoxStart = fps * 1;
  const tBoxEnd = fps * 2;
  const tZoomStart = fps * 2.5;
  const tZoomEnd = fps * 4.5;
  const tFocusEnd = fps * 5;
  const tReadStart = fps * 5.5;
  const tReadEnd = totalFrames - fps * 1;

  // Words array for highlighting
  const words = mainMessage.trim().split(/\s+/);
  const framesPerWord = 6;
  const actualReadEnd = Math.min(tReadEnd, tReadStart + (words.length + 2) * framesPerWord);

  // Animations
  const globalOpacity = interpolate(frame, [0, tSetup], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  
  const boxDraw = interpolate(frame, [tBoxStart, tBoxEnd], [0, 1], { 
    easing: Easing.inOut(Easing.ease), extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });

  const zoomProgress = interpolate(frame, [tZoomStart, tZoomEnd], [0, 1], { 
    easing: Easing.inOut(Easing.cubic), extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });

  // Camera Focus blur effect (blurs while moving, sharpens when stopped)
  const blurAmount = interpolate(frame, [tZoomStart, tZoomEnd, tFocusEnd], [0, 10, 0], { 
    extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });

  const readingProgress = interpolate(frame, [tReadStart, actualReadEnd], [0, words.length + 2], { 
    extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });

  // Target coordinates mapping for 16:9 center focus
  const targetCx = 1980;
  const targetCy = 1030;
  
  const initialScale = Math.min(width / bpW, height / bpH);
  const targetScale = 2.0;

  const startTranslateX = (width - bpW * initialScale) / 2;
  const startTranslateY = (height - bpH * initialScale) / 2;

  const endTranslateX = width / 2 - targetCx * targetScale;
  const endTranslateY = height / 2 - targetCy * targetScale;

  const currentScale = interpolate(zoomProgress, [0, 1], [initialScale, targetScale]);
  const translateX = interpolate(zoomProgress, [0, 1], [startTranslateX, endTranslateX]);
  const translateY = interpolate(zoomProgress, [0, 1], [startTranslateY, endTranslateY]);

  // Render logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Deterministic skeleton notes generator
  const renderSkeleton = (cIdx: number, colW: number) => {
    let y = 0;
    const lines = [];
    for (let i = 0; i < 150; i++) {
      const isHeading = random(`h-${cIdx}-${i}`) > 0.85;
      const h = isHeading ? 20 : 10;
      const w = isHeading ? colW * 0.4 : colW * (0.5 + random(`w-${cIdx}-${i}`) * 0.45);
      
      y += h + 24 + (isHeading ? 16 : 0);
      
      if (y > bpH - 150) break;
      
      // Leave empty space for our target note in Column 2
      if (cIdx === 2 && y > 750 && y < 1350) {
        continue;
      }

      lines.push(
        <div key={i} style={{ 
          position: "absolute", top: y, left: 0, width: w, height: h, 
          backgroundColor: textColor, opacity: 0.12, borderRadius: 2 
        }} />
      );
    }
    return lines;
  };

  const columns = [
    { x: 80, w: 680 },
    { x: 860, w: 680 },
    { x: 1640, w: 680 },
    { x: 2420, w: 680 },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: robotoMono }}>
      <div style={{
        position: "absolute",
        width: bpW,
        height: bpH,
        transformOrigin: "0 0",
        transform: `translate(${translateX}px, ${translateY}px) scale(${currentScale})`,
        backgroundColor: bgColor,
        opacity: globalOpacity,
        filter: `blur(${blurAmount}px)`,
        boxShadow: "0 0 100px rgba(0,0,0,0.1)",
        backgroundImage: `linear-gradient(to right, ${textColor}10 1px, transparent 1px), linear-gradient(to bottom, ${textColor}10 1px, transparent 1px)`,
        backgroundSize: "40px 40px",
      }}>
        
        {/* Borders */}
        <div style={{ position: "absolute", left: 40, top: 40, right: 40, bottom: 40, border: `8px solid ${textColor}` }} />
        
        {/* Column Dividers */}
        <div style={{ position: "absolute", left: 820, top: 40, width: 4, bottom: 40, backgroundColor: textColor }} />
        <div style={{ position: "absolute", left: 1600, top: 40, width: 4, bottom: 40, backgroundColor: textColor }} />
        <div style={{ position: "absolute", left: 2380, top: 40, width: 4, bottom: 40, backgroundColor: textColor }} />
        <div style={{ position: "absolute", left: 3160, top: 40, width: 4, bottom: 40, backgroundColor: textColor }} />

        {/* Title Block Horizontals (Right Side) */}
        <div style={{ position: "absolute", left: 3160, top: 240, width: 640, height: 4, backgroundColor: textColor }} />
        <div style={{ position: "absolute", left: 3160, top: 480, width: 640, height: 4, backgroundColor: textColor }} />
        <div style={{ position: "absolute", left: 3160, top: 720, width: 640, height: 4, backgroundColor: textColor }} />
        <div style={{ position: "absolute", left: 3160, top: 1100, width: 640, height: 4, backgroundColor: textColor }} />
        <div style={{ position: "absolute", left: 3160, top: 1800, width: 640, height: 4, backgroundColor: textColor }} />
        
        {/* Title Block Texts */}
        <TitleBlockText y={100} label="PROJECT NO." value="765014-01" color={textColor} />
        <TitleBlockText y={320} label="SCALE" value="AS NOTED" color={textColor} />
        <TitleBlockText y={560} label="DATE" value="11/21/2024" color={textColor} />
        <TitleBlockText y={1860} label="DRAWN BY" value="MALLOY" color={textColor} />
        <TitleBlockText y={1980} label="CHECKED BY" value="CAVE" color={textColor} />

        {/* Vertical Branding */}
        <div style={{ position: "absolute", left: 3160, top: 1100, width: 640, height: 700, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ transform: "rotate(-90deg)", fontSize: 80, fontWeight: "bold", letterSpacing: 12, color: textColor, whiteSpace: "nowrap" }}>
            {brandingText}
          </div>
        </div>

        {/* Official Seal */}
        <svg style={{ position: "absolute", left: 3380, top: 810, width: 200, height: 200, opacity: 0.85 }}>
          <circle cx="100" cy="100" r="80" fill="none" stroke={stampColor} strokeWidth="6" strokeDasharray="12 4" />
          <circle cx="100" cy="100" r="70" fill="none" stroke={stampColor} strokeWidth="2" />
          <path id="curve" d="M 30 100 A 70 70 0 0 1 170 100" fill="transparent" />
          <text fill={stampColor} fontSize="18" fontWeight="bold" letterSpacing="4">
            <textPath href="#curve" startOffset="50%" textAnchor="middle">APPROVED</textPath>
          </text>
          <text x="100" y="115" fill={stampColor} fontSize="28" fontWeight="bold" textAnchor="middle">SEAL</text>
          <text x="100" y="140" fill={stampColor} fontSize="12" fontWeight="bold" textAnchor="middle">FLORIDA</text>
        </svg>

        {/* Skeleton Notes */}
        {columns.map((col, cIdx) => (
          <div key={cIdx} style={{ position: "absolute", left: col.x, top: 80, width: col.w, height: bpH }}>
            {renderSkeleton(cIdx, col.w)}
          </div>
        ))}

        {/* Target Focus Note */}
        <div style={{
          position: "absolute", left: 1680, top: 840, width: 600, height: 400,
          display: "flex", flexDirection: "column", gap: 20
        }}>
          <div style={{ fontSize: 32, fontWeight: 700, borderBottom: `4px solid ${textColor}`, paddingBottom: 12, color: textColor }}>
            {noteTitle}
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px 10px", fontSize: 28, lineHeight: 1.4, fontWeight: 500, color: textColor }}>
            {words.map((word, i) => {
              const p = interpolate(readingProgress - i, [0, 1], [0, 100], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
              return (
                <span key={i} style={{ position: "relative", padding: "0 4px" }}>
                  <span style={{ position: "relative", zIndex: 1, color: textColor }}>{word}</span>
                  <span style={{
                    position: "absolute", top: 0, left: 0, bottom: 0, width: `${p}%`,
                    backgroundColor: highlightColor,
                    mixBlendMode: "multiply",
                    borderRadius: 4,
                  }} />
                </span>
              );
            })}
          </div>
        </div>

        {/* Drawing Selection Box */}
        {boxDraw > 0 && (
          <svg style={{ position: "absolute", top: 810, left: 1650, width: 660, height: 440, overflow: "visible" }}>
            <rect 
              x={0} y={0} width={660} height={440} rx={12} ry={12}
              fill="none" 
              stroke={selectionColor} 
              strokeWidth={8} 
              strokeLinecap="round"
              strokeDasharray={2500} 
              strokeDashoffset={2500 * (1 - boxDraw)}
            />
          </svg>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default BlueprintRead;